#!/usr/bin/env node
/**
 * Cleanup assets generated by scripts/prepare-test-assets.js and test runtime artifacts.
 */
const fs = require('node:fs');
const path = require('node:path');

const repoRoot = path.resolve(__dirname, '..');

function toRepoRelative(filePath) {
  return path.relative(repoRoot, filePath).replace(/\\/g, '/');
}

function removePath(filePath) {
  if (!fs.existsSync(filePath)) return false;
  fs.rmSync(filePath, { recursive: true, force: true });
  return true;
}

function removeEmptyDir(dirPath) {
  if (!fs.existsSync(dirPath)) return;
  const entries = fs.readdirSync(dirPath);
  if (entries.length === 0) {
    fs.rmdirSync(dirPath);
  }
}
function cleanupPreparedAssets() {
  const targetFiles = [
    'env-automated-tests.settings',
    'env-opencode-optimized.settings',
    '.mcp-local-llm/AGENTS.md',
  ];

  for (const relPath of targetFiles) {
    const filePath = path.join(repoRoot, relPath);
    if (removePath(filePath)) {
      console.log(`[cleanup-test-assets] removed ${toRepoRelative(filePath)}`);
    }
  }

  const mcpDir = path.join(repoRoot, '.mcp-local-llm');
  removeEmptyDir(mcpDir);
}

function cleanupDistPackage() {
  const distPath = path.join(repoRoot, 'dist_package');
  if (removePath(distPath)) {
    console.log('[cleanup-test-assets] removed dist_package');
  }
}

function cleanupRuntimeArtifacts() {
  const runtimePaths = [
    'test-results',
    'tests/tmp',
    'tests/tmp.bin',
    'tests/.mcp-backups',
    'tests/.mcp_cache',
    '.mcp-backups/tests',
    '.tmp/test-orchestration-plans',
    '.tmp/test-assets-state.json',
  ];

  for (const relPath of runtimePaths) {
    const absPath = path.join(repoRoot, relPath);
    if (removePath(absPath)) {
      console.log(`[cleanup-test-assets] removed ${relPath}`);
    }
  }

  removeEmptyDir(path.join(repoRoot, '.tmp'));
}

function main() {
  cleanupPreparedAssets();
  cleanupDistPackage();
  cleanupRuntimeArtifacts();
}

main();
